// Łączy produkty + warianty w jedną listę z poziomem OK / LOW / OUT.
// Próg niskiego stanu ustawiasz w węźle "Ustawienia" (low_max).
const cfg = $('Ustawienia').first().json;
const LOW_MAX = Number(cfg.low_max);
const decode = s => String(s || '').split('&amp;').join('&').split('&#8211;').join('–').split('&#8217;').join('’').split('&#039;').join("'").split('&quot;').join('"');
const rawProducts = $('Pobierz produkty').all().map(i => i.json);
const products = rawProducts.filter(p => p && p.id && (!p.status || p.status === 'publish'));
const varsByParent = {};
for (const it of $input.all()) {
  const v = it.json;
  if (!v || !v.id) continue;
  if (v.status && v.status !== 'publish') continue;
  let pid = v.parent_id;
  if (!pid && it.pairedItem) {
    const pi = Array.isArray(it.pairedItem) ? it.pairedItem[0] : it.pairedItem;
    const src = pi && rawProducts[pi.item];
    if (src) pid = src.id;
  }
  if (!pid) continue;
  (varsByParent[pid] = varsByParent[pid] || []).push(v);
}
const num = x => { const n = parseFloat(x); return isFinite(n) ? n : 0; };
const qtyOf = x => (x === null || x === undefined || x === '') ? 0 : Number(x);
const levelOf = (qty, status) => qty !== null
  ? (qty <= 0 ? 'OUT' : (qty <= LOW_MAX ? 'LOW' : 'OK'))
  : (status === 'instock' ? 'OK' : 'OUT');
const rows = [];
for (const p of products) {
  const name = decode(p.name);
  const parentQty = p.manage_stock === true ? qtyOf(p.stock_quantity) : null;
  const vs = varsByParent[p.id] || [];
  if (p.type === 'variable') {
    for (const v of vs) {
      let qty = null;
      let pool = 'v' + v.id;
      if (v.manage_stock === true) qty = qtyOf(v.stock_quantity);
      else if (v.manage_stock === 'parent') { qty = parentQty; pool = 'p' + p.id; }
      const label = (v.attributes || []).map(a => decode(a.option || a.name)).filter(Boolean).join(' / ') || ('#' + v.id);
      rows.push({ variation_id: v.id, product_id: p.id, product: name, variant: label, qty, level: levelOf(qty, v.stock_status), price: num(v.price), permalink: p.permalink, pool });
    }
  } else {
    rows.push({ variation_id: p.id, product_id: p.id, product: name, variant: '', qty: parentQty, level: levelOf(parentQty, p.stock_status), price: num(p.price), permalink: p.permalink, pool: 'p' + p.id });
  }
}
const pools = {};
for (const r of rows) if (r.qty !== null && !(r.pool in pools)) pools[r.pool] = r;
let units = 0;
let value = 0;
for (const k of Object.keys(pools)) {
  const r = pools[k];
  if (r.qty > 0) { units += r.qty; value += r.qty * r.price; }
}
const unknown = rows.filter(r => r.qty === null && r.level === 'OK').length;
return [{ json: {
  mode: cfg.mode,
  low_max: LOW_MAX,
  rows,
  totals: { units, value: Math.round(value * 100) / 100, unknown, variants: rows.length, products: products.length }
} }];

const n = $('Normalizuj stany').first().json;
const NL = String.fromCharCode(10);
const money = v => {
  const parts = (Math.round(v * 100) / 100).toFixed(2).split('.');
  let s = parts[0];
  let out = '';
  while (s.length > 3) { out = ' ' + s.slice(-3) + out; s = s.slice(0, -3); }
  return s + out + ',' + parts[1] + ' zł';
};
const fmtQty = r => r.qty === null ? 'brak' : String(r.qty);
const groups = {};
const order = [];
for (const r of n.rows) {
  if (r.level === 'OK') continue;
  if (!groups[r.product_id]) { groups[r.product_id] = { name: r.product, url: r.permalink, out: [], low: [] }; order.push(r.product_id); }
  const label = r.variant || 'produkt';
  if (r.level === 'OUT') groups[r.product_id].out.push(label);
  else groups[r.product_id].low.push(label + ' (' + fmtQty(r) + ')');
}
const lowCount = n.rows.filter(r => r.level === 'LOW').length;
const outCount = n.rows.filter(r => r.level === 'OUT').length;
const lines = [];
for (const pid of order) {
  const g = groups[pid];
  const bits = [];
  if (g.out.length) bits.push('brak: ' + g.out.join(', '));
  if (g.low.length) bits.push('niski: ' + g.low.join(', '));
  lines.push('**[' + g.name + '](' + g.url + ')** — ' + bits.join(' · '));
}
let description = lines.length ? '' : 'Wszystkie warianty powyżej progu niskiego stanu.';
let shown = 0;
for (const l of lines) {
  if ((description + l).length > 3700) break;
  description += (description ? NL : '') + l;
  shown += 1;
}
if (shown < lines.length) description += NL + '… i jeszcze ' + (lines.length - shown) + ' produktów';
if (n.totals.unknown > 0) description += NL + NL + '_' + n.totals.unknown + ' wariantów bez śledzenia ilości (nie liczone w sumach)._';
const embed = {
  title: '📦 Stany magazynowe — przegląd tygodniowy',
  description,
  color: outCount > 0 ? 15158332 : (lowCount > 0 ? 15844367 : 3066993),
  fields: [
    { name: 'Sztuk na stanie', value: n.totals.units + ' szt.', inline: true },
    { name: 'Wartość (brutto)', value: money(n.totals.value), inline: true },
    { name: 'Niski stan / brak', value: lowCount + ' / ' + outCount + ' wariantów', inline: true }
  ],
  footer: { text: 'Niski stan = 1–' + n.low_max + ' szt. · ' + n.totals.variants + ' wariantów w ' + n.totals.products + ' produktach' },
  timestamp: new Date().toISOString()
};
return [{ json: { embed: JSON.stringify(embed), lowCount, outCount, units: n.totals.units, value: n.totals.value } }];

// Porównuje bieżące stany z zapisanymi w lunae_stock_state.
// Pusta tabela = pierwsze uruchomienie: zapis bez alertów + jedno podsumowanie "stan początkowy".
const cur = $('Normalizuj stany').first().json;
const prev = $input.all().map(i => i.json).filter(r => r && r.variation_id !== undefined && r.variation_id !== null);
const firstRun = prev.length === 0;
const prevById = {};
for (const r of prev) prevById[Number(r.variation_id)] = r;
const nowIso = new Date().toISOString();
const toRow = r => ({ variation_id: r.variation_id, product_id: r.product_id, product: r.product, variant: r.variant, level: r.level, qty: r.qty, updated_at: nowIso });
const kindOf = (from, to) => to === 'OUT' ? 'out' : (to === 'LOW' ? ((from === 'OK' || from === 'NEW') ? 'low' : 'back') : 'back');
const transitions = [];
const upserts = [];
for (const r of cur.rows) {
  const p = prevById[Number(r.variation_id)];
  if (!p) {
    upserts.push(toRow(r));
    if (!firstRun && r.level !== 'OK') transitions.push(Object.assign({}, r, { from: 'NEW', prevQty: null, kind: kindOf('NEW', r.level) }));
    continue;
  }
  const pq = (p.qty === undefined || p.qty === null || p.qty === '') ? null : Number(p.qty);
  if (p.level !== r.level) {
    transitions.push(Object.assign({}, r, { from: p.level, prevQty: pq, kind: kindOf(p.level, r.level) }));
    upserts.push(toRow(r));
  } else if (pq !== r.qty || p.product !== r.product || p.variant !== r.variant) {
    upserts.push(toRow(r));
  }
}
const byProduct = {};
for (const r of cur.rows) (byProduct[r.product_id] = byProduct[r.product_id] || []).push(r);
const candidatePids = firstRun
  ? Object.keys(byProduct).map(Number)
  : Array.from(new Set(transitions.filter(t => t.kind === 'out').map(t => t.product_id)));
const soldOut = candidatePids
  .filter(pid => byProduct[pid] && byProduct[pid].length && byProduct[pid].every(r => r.level === 'OUT'))
  .map(pid => ({ product_id: pid, name: byProduct[pid][0].product, permalink: byProduct[pid][0].permalink }));
return [{ json: {
  firstRun,
  hasMessage: firstRun || transitions.length > 0,
  needMeta: soldOut.length > 0,
  transitions,
  soldOut,
  upserts,
  current: firstRun ? cur.rows.filter(r => r.level !== 'OK') : [],
  totals: cur.totals,
  low_max: cur.low_max
} }];

const c = $('Porównaj stany').first().json;
const NL = String.fromCharCode(10);
const stamp = $now.setZone('Europe/Warsaw').toFormat('dd.MM.yyyy HH:mm');
// --- Meta: aktywne reklamy kierujące na wyprzedany produkt (tylko odczyt) ---
const adsByProduct = {};
let metaNote = '';
if (c.needMeta) {
  let m = null;
  try { m = $('Meta: aktywne reklamy').isExecuted ? $('Meta: aktywne reklamy').first().json : null; } catch (e) { m = null; }
  if (!m || m.error || !Array.isArray(m.data)) {
    metaNote = '_(nie udało się sprawdzić reklam w Meta)_';
  } else {
    for (const p of c.soldOut) {
      const name = String(p.name || '').toLowerCase().trim();
      let slugPath = '';
      try { slugPath = new URL(p.permalink).pathname.toLowerCase().replace(/[/]+$/, ''); } catch (e) { slugPath = ''; }
      const tokens = [name, name.split(' ').join('-'), slugPath].filter(t => t && t.length >= 6);
      const hits = m.data.filter(ad => {
        const hay = JSON.stringify({ n: ad.name, c: ad.creative || {} }).toLowerCase();
        let decoded = hay;
        try { decoded = decodeURIComponent(hay); } catch (e) { decoded = hay; }
        return tokens.some(t => hay.includes(t) || decoded.includes(t));
      });
      if (hits.length) adsByProduct[p.product_id] = hits.map(a => a.name);
    }
  }
}
const fmtQty = (q, lvl) => q === null || q === undefined ? (lvl === 'OUT' ? 'brak' : 'dostępny') : q + ' szt.';
const levelPL = { OK: 'ok', LOW: 'niski', OUT: 'brak', NEW: 'nowy' };
const kindPL = { low: 'niski stan', out: 'wyprzedane', back: 'znów dostępne' };
const soldOutIds = {};
for (const p of c.soldOut) soldOutIds[p.product_id] = true;
const soldOutLines = pid => {
  if (!soldOutIds[pid]) return [];
  const out = ['  Cały produkt wyprzedany.'];
  if (adsByProduct[pid]) out.push('  ⚠️ reklama nadal aktywna: ' + adsByProduct[pid].join(', '));
  else if (metaNote) out.push('  ' + metaNote);
  return out;
};
const blocks = [];
let header;
if (c.firstRun) {
  header = '📦 **Stany magazynowe — stan początkowy** · ' + stamp + NL +
    'Monitoring włączony: ' + c.totals.variants + ' wariantów, ' + c.totals.units + ' szt. Niski stan = 1–' + c.low_max + ' szt. Kolejne wiadomości tylko przy zmianach.';
  const groups = {};
  const order = [];
  for (const r of c.current) {
    if (!groups[r.product_id]) { groups[r.product_id] = { name: r.product, url: r.permalink, out: [], low: [] }; order.push(r.product_id); }
    if (r.level === 'OUT') groups[r.product_id].out.push(r.variant || 'produkt');
    else groups[r.product_id].low.push((r.variant || 'produkt') + ' (' + fmtQty(r.qty, r.level) + ')');
  }
  if (!order.length) blocks.push(['Wszystkie warianty powyżej progu.']);
  for (const pid of order) {
    const g = groups[pid];
    const bits = [];
    if (g.out.length) bits.push('brak: ' + g.out.join(', '));
    if (g.low.length) bits.push('niski: ' + g.low.join(', '));
    blocks.push(['**' + g.name + '** — ' + bits.join(' · ') + ' — <' + g.url + '>'].concat(soldOutLines(pid)));
  }
} else {
  const anyOut = c.transitions.some(t => t.kind === 'out');
  const anyLow = c.transitions.some(t => t.kind === 'low');
  const emoji = anyOut ? '🔴' : (anyLow ? '🟡' : '🟢');
  header = emoji + ' **Stany magazynowe — zmiany** · ' + stamp;
  const rank = { out: 0, low: 1, back: 2 };
  const groups = {};
  const order = [];
  const sorted = c.transitions.slice().sort((a, b) => rank[a.kind] - rank[b.kind]);
  for (const t of sorted) {
    if (!groups[t.product_id]) { groups[t.product_id] = { name: t.product, url: t.permalink, items: [] }; order.push(t.product_id); }
    const was = t.prevQty !== null && t.prevQty !== undefined ? ' (było ' + t.prevQty + ')' : (t.from === 'NEW' ? ' (nowy wariant)' : ' (wcześniej: ' + levelPL[t.from] + ')');
    groups[t.product_id].items.push('• ' + (t.variant || 'produkt') + ': ' + fmtQty(t.qty, t.level) + was + ' — ' + kindPL[t.kind]);
  }
  for (const pid of order) {
    const g = groups[pid];
    blocks.push(['**' + g.name + '** — <' + g.url + '>'].concat(g.items, soldOutLines(pid)));
  }
}
let content = header;
let shown = 0;
for (const b of blocks) {
  const chunk = NL + b.join(NL);
  if ((content + chunk).length > 1880) break;
  content += chunk;
  shown += 1;
}
if (shown < blocks.length) content += NL + '… i jeszcze ' + (blocks.length - shown) + ' produktów (pełna lista w panelu WooCommerce).';
return [{ json: { content, length: content.length, firstRun: c.firstRun, transitions: c.transitions.length, soldOut: c.soldOut.map(p => p.name), adsFlagged: adsByProduct, metaNote } }];
